const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const arabianSea = ee.Geometry.Polygon(
    [[[50.0, 25.0],
      [75.0, 25.0],
      [75.0, 5.0],
      [50.0, 5.0],
      [50.0, 25.0]]]
  );

  const startDate = '2023-06-01';
  const endDate = '2023-06-30';

  // 2. Data Acquisition & Check
  let sstCollection = ee.ImageCollection('NOAA/AVHRR/OISSTU/V2')
    .filterDate(startDate, endDate)
    .filterBounds(arabianSea)
    .select('sst'); // Select the Sea Surface Temperature band

  const collectionSize = await sstCollection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No OISST data found for June 2023 in the Arabian Sea.");
    console.log("C1");
    return;
  }

  console.log(`Images found for June 2023: ${collectionSize}`);

  // Create a single image representing the maximum SST over the period
  const maxSstImage = sstCollection.max();

  // 3. Processing (Calculate pixel count to detect C2)
  // Check for valid pixels in the maxSstImage within the geometry
  const pixelCount = await maxSstImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: arabianSea,
    scale: 1000, // Use a sufficiently large scale to prevent timeout
    maxPixels: 1e9,
    tileScale: 16
  }).get('sst').getInfo();

  if (pixelCount === 0 || pixelCount === null) {
    console.log("No valid pixels remain after filtering and masking within the Arabian Sea for SST.");
    console.log("C2");
    return;
  }
  console.log(`Valid pixels count: ${pixelCount}`);


  // 4. Calculation
  const maxSst = await maxSstImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: arabianSea,
    scale: 1000, // Use a sufficiently large scale
    maxPixels: 1e9,
    tileScale: 16
  }).get('sst').getInfo();

  // 5. Validation & Final Answer
  if (maxSst === null || isNaN(maxSst)) {
    console.log("Calculation for maximum SST returned an invalid result (null or NaN).");
    console.log("C3");
    return;
  }

  console.log(`Maximum Sea Surface Temperature in June 2023: ${maxSst.toFixed(2)} °C`);

  if (maxSst >= 30) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
